INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0203-0001-0001-000000000001', '22222222-0002-0001-0001-000000000003', 'Greater Than, Less Than', 'The history of inequality symbols and what they mean', 1, 'tutorial', 15, 5, 1631, 'Thomas Harriot',
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0203-0001-0001-000000000001', '33333333-0203-0001-0001-000000000001', 'multiple_choice', 'easy', 'Who invented the < and > symbols?', NULL, '[{"id":"a","text":"Pythagoras"},{"id":"b","text":"Thomas Harriot"},{"id":"c","text":"Isaac Newton"},{"id":"d","text":"Euclid"}]'::jsonb, '"b"'::jsonb, 'Thomas Harriot invented < and > symbols, published in 1631 after his death.', 'He also explored Virginia with Sir Walter Raleigh', 5, 1),
('44444444-0203-0001-0001-000000000002', '33333333-0203-0001-0001-000000000001', 'true_false', 'easy', 'True or False: 5 > 3 means "5 is greater than 3."', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! The wide end of > points to the bigger number (5), the pointed end to the smaller (3).', 'The open end faces the bigger number', 5, 2),
('44444444-0203-0001-0001-000000000003', '33333333-0203-0001-0001-000000000001', 'multiple_choice', 'easy', 'Which symbol means "less than or equal to"?', NULL, '[{"id":"a","text":"<"},{"id":"b","text":">"},{"id":"c","text":"≤"},{"id":"d","text":"≠"}]'::jsonb, '"c"'::jsonb, '≤ means less than or equal to. It was introduced by Pierre Bouguer in 1734 — a line under the < symbol.', 'It combines < with =', 5, 3),
('44444444-0203-0001-0001-000000000004', '33333333-0203-0001-0001-000000000001', 'multiple_choice', 'easy', 'Which is true?', NULL, '[{"id":"a","text":"7 < 3"},{"id":"b","text":"4 > 9"},{"id":"c","text":"6 ≥ 6"},{"id":"d","text":"5 ≤ 2"}]'::jsonb, '"c"'::jsonb, '6 ≥ 6 is true because ≥ means "greater than OR equal to" and 6 equals 6. The others are false.', '≥ includes the case where both sides are equal', 5, 4),
('44444444-0203-0001-0001-000000000005', '33333333-0203-0001-0001-000000000001', 'true_false', 'easy', 'True or False: -3 > -1', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'False! On a number line, -3 is further left than -1, so -3 < -1. With negatives, the number closer to zero is bigger.', 'Picture a number line — which is further right?', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0203-0001-0001-000000000002', '22222222-0002-0001-0001-000000000003', 'Solving Inequalities', 'Use the balance method to solve inequalities', 2, 'practice', 10, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0203-0002-0001-000000000001', '33333333-0203-0001-0001-000000000002', 'multiple_choice', 'easy', 'Solve: x + 4 > 9. Which values of x work?', 'x + 4 > 9', '[{"id":"a","text":"x > 5"},{"id":"b","text":"x > 13"},{"id":"c","text":"x < 5"},{"id":"d","text":"x = 5"}]'::jsonb, '"a"'::jsonb, 'Subtract 4 from both sides: x > 5. Any number greater than 5 (like 6, 7, 100) makes this true.', 'Solve it like an equation — subtract 4 from both sides', 5, 1),
('44444444-0203-0002-0001-000000000002', '33333333-0203-0001-0001-000000000002', 'multiple_choice', 'easy', 'Solve: 3x ≤ 12', '3x \\leq 12', '[{"id":"a","text":"x ≤ 4"},{"id":"b","text":"x ≥ 4"},{"id":"c","text":"x ≤ 36"},{"id":"d","text":"x < 4"}]'::jsonb, '"a"'::jsonb, 'Divide both sides by 3: x ≤ 4. The ≤ sign stays the same when dividing by a positive number.', 'Divide both sides by 3, same as an equation', 5, 2),
('44444444-0203-0002-0001-000000000003', '33333333-0203-0001-0001-000000000002', 'true_false', 'easy', 'True or False: When you multiply or divide an inequality by a negative number, you must flip the inequality sign.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! This is the KEY rule. For example, -2x > 6 becomes x < -3 (sign flips when dividing by -2).', 'This is the one rule that differs from equations', 5, 3),
('44444444-0203-0002-0001-000000000004', '33333333-0203-0001-0001-000000000002', 'multiple_choice', 'medium', 'Solve: -2x > 8', '-2x > 8', '[{"id":"a","text":"x > -4"},{"id":"b","text":"x < -4"},{"id":"c","text":"x > 4"},{"id":"d","text":"x < 4"}]'::jsonb, '"b"'::jsonb, 'Divide by -2 AND flip the sign: x < -4. When dividing by a negative, > becomes <.', 'Remember to flip the sign when dividing by a negative', 10, 4),
('44444444-0203-0002-0001-000000000005', '33333333-0203-0001-0001-000000000002', 'fill_in_blank', 'easy', 'Solve: n - 7 ≥ 3. What is the smallest whole number n can be?', 'n - 7 \\geq 3', NULL, '"10"'::jsonb, 'Add 7: n ≥ 10. The smallest whole number that satisfies this is 10 itself (since ≥ includes equality).', 'Add 7 to both sides, then find the boundary', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0203-0001-0001-000000000003', '22222222-0002-0001-0001-000000000003', 'Graphing Inequalities', 'Visualize solutions on a number line', 3, 'practice', 10, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0203-0003-0001-000000000001', '33333333-0203-0001-0001-000000000003', 'multiple_choice', 'easy', 'On a number line graph of x > 3, what goes at the point 3?', NULL, '[{"id":"a","text":"A filled (closed) circle"},{"id":"b","text":"An open circle"},{"id":"c","text":"An arrow"},{"id":"d","text":"Nothing"}]'::jsonb, '"b"'::jsonb, 'An open circle at 3 means 3 is NOT included (strictly greater than). A filled circle would mean ≥ (included).', 'Is 3 itself part of the solution?', 5, 1),
('44444444-0203-0003-0001-000000000002', '33333333-0203-0001-0001-000000000003', 'true_false', 'easy', 'True or False: For x ≤ 5, the graph uses a filled circle at 5 and an arrow pointing left.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! Filled circle because ≤ includes 5. Arrow left because the solutions are 5 and everything less than 5.', '≤ includes the boundary point (filled) and goes toward smaller numbers (left)', 5, 2),
('44444444-0203-0003-0001-000000000003', '33333333-0203-0001-0001-000000000003', 'multiple_choice', 'easy', 'Which inequality matches a number line with a filled circle at -2 and an arrow pointing right?', NULL, '[{"id":"a","text":"x > -2"},{"id":"b","text":"x < -2"},{"id":"c","text":"x ≥ -2"},{"id":"d","text":"x ≤ -2"}]'::jsonb, '"c"'::jsonb, 'Filled circle = includes the point (≥ or ≤). Arrow right = greater than. So x ≥ -2.', 'Filled = includes, right = greater', 5, 3),
('44444444-0203-0003-0001-000000000004', '33333333-0203-0001-0001-000000000003', 'multiple_choice', 'easy', 'How many solutions does x > 3 have?', NULL, '[{"id":"a","text":"Exactly one: x = 4"},{"id":"b","text":"None"},{"id":"c","text":"Infinitely many"},{"id":"d","text":"Exactly three"}]'::jsonb, '"c"'::jsonb, 'Infinitely many! 3.1, 3.5, 4, 10, 1000 — any number greater than 3 is a solution. That is why we draw an arrow.', 'Think about all the numbers bigger than 3', 5, 4),
('44444444-0203-0003-0001-000000000005', '33333333-0203-0001-0001-000000000003', 'multiple_choice', 'medium', 'Which value is NOT a solution to x ≥ -1?', NULL, '[{"id":"a","text":"0"},{"id":"b","text":"-1"},{"id":"c","text":"100"},{"id":"d","text":"-2"}]'::jsonb, '"d"'::jsonb, '-2 is less than -1, so it does not satisfy x ≥ -1. All the others are greater than or equal to -1.', 'Which number is to the left of -1 on the number line?', 10, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0203-0001-0001-000000000004', '22222222-0002-0001-0001-000000000003', 'Inequalities Boss Round', 'Master the world of inequalities!', 4, 'boss_round', 25, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0203-0004-0001-000000000001', '33333333-0203-0001-0001-000000000004', 'fill_in_blank', 'medium', 'Solve: 2x + 5 > 13. x is greater than what number?', '2x + 5 > 13', NULL, '"4"'::jsonb, 'Subtract 5: 2x > 8. Divide by 2: x > 4.', 'Two steps: subtract 5, then divide by 2', 10, 1),
('44444444-0203-0004-0001-000000000002', '33333333-0203-0001-0001-000000000004', 'multiple_choice', 'medium', 'Solve: -5x ≤ 20', '-5x \\leq 20', '[{"id":"a","text":"x ≤ -4"},{"id":"b","text":"x ≥ -4"},{"id":"c","text":"x ≤ 4"},{"id":"d","text":"x ≥ 4"}]'::jsonb, '"b"'::jsonb, 'Divide by -5 AND flip the sign: x ≥ -4. Remember: dividing by a negative flips ≤ to ≥.', 'Flip the sign when dividing by a negative!', 10, 2),
('44444444-0203-0004-0001-000000000003', '33333333-0203-0001-0001-000000000004', 'true_false', 'medium', 'True or False: The solution to x + 3 < x + 5 is "all real numbers."', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! Subtract x from both sides: 3 < 5, which is always true. Every number works!', 'Try subtracting x from both sides', 10, 3),
('44444444-0203-0004-0001-000000000004', '33333333-0203-0001-0001-000000000004', 'multiple_choice', 'medium', 'Thomas Harriot is also known for which non-mathematical achievement?', NULL, '[{"id":"a","text":"Discovering gravity"},{"id":"b","text":"Mapping parts of Virginia"},{"id":"c","text":"Building the pyramids"},{"id":"d","text":"Inventing the telescope"}]'::jsonb, '"b"'::jsonb, 'Harriot sailed to Virginia with Sir Walter Raleigh, mapping the territory and learning the Algonquian language. A mathematician AND an explorer!', 'He sailed with Sir Walter Raleigh', 10, 4),
('44444444-0203-0004-0001-000000000005', '33333333-0203-0001-0001-000000000004', 'fill_in_blank', 'medium', 'Solve: 3 - x ≥ 7. x is less than or equal to what number?', '3 - x \\geq 7', NULL, '"-4"'::jsonb, 'Subtract 3: -x ≥ 4. Multiply by -1 (flip!): x ≤ -4.', 'Subtract 3 first, then multiply by -1 and flip', 10, 5)
